class FenwickTree:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def update(self, i, delta):
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i  # Move to next index

    def query(self, i):
        sum = 0
        while i > 0:
            sum += self.bit[i]
            i -= i & -i  # Move to parent
        return sum

    def range_query(self, l, r):
        return self.query(r) - self.query(l - 1)

class FenwickTree2D:
    def __init__(self, m, n):
        self.m, self.n = m, n
        self.bit = [[0] * (n + 1) for _ in range(m + 1)]

    def update(self, x, y, delta):
        i = x
        while i <= self.m:
            j = y
            while j <= self.n:
                self.bit[i][j] += delta
                j += j & -j
            i += i & -i

    def query(self, x, y):
        sum = 0
        i = x
        while i > 0:
            j = y
            while j > 0:
                sum += self.bit[i][j]
                j -= j & -j
            i -= i & -i
        return sum
